const execution = $json.execution || {};
const error = execution.error || {};
const message = error.message || '不明なエラー';
const url = execution.url || '';
const workflow = execution.workflow?.name || '不明なワークフロー';

const isCookieError = /twitter|auth|cookie|login|401|403/i.test(message);

let text = `🚨 *n8n ワークフローエラー*\n`;
text += `ワークフロー: ${workflow}\n`;
text += `エラー: ${message}\n`;
if (url) text += `実行URL: ${url}\n`;

if (isCookieError) {
  text += '\n⚠️ *X Cookie の再設定が必要な可能性があります*\n';
  text += '手順:\n';
  text += '1. ブラウザで X にログイン → DevTools → Cookies → auth_token と ct0 を取得\n';
  text += '2. ホストで `twitter login` を実行（Cookie再設定）\n';
  text += '3. data/twitter-cli/ に認証ファイルが反映されていることを確認\n';
}

return [{ json: { text } }];
